{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Perindopril has an absolute oral bioavailability of about 75% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Nicainoprol oral bioavailability based on AUC averaged 69.4% (range 59.1–92.4%) after a 200 mg oral dose compared with IV in eight human subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "S-9780 bioavailability was 19% ±7% in young healthy subjects after oral 8 mg perindopril, below the 20% threshold and arguing against high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most molecule-level evidence from absolute oral bioavailability measurements in humans supports high (F ≥20%), including values of 75%, 69.4%, 52%, 46%, 28%, and 20%; one direct measurement at 19% is contradictory. Overall high is better supported, but the threshold is close for several records.",
  "evidence_gaps": [
    "One direct measurement (C40) is below the 20% threshold at 19% ±7%, conflicting with the majority high prediction.",
    "Molecule 1 has both above- and below-threshold absolute measurements (e.g., C32 23.5% vs C46 15.8%), so its direction is not fully consistent.",
    "Some records are qualitative or unspecified endpoint (e.g., C01 'nearly complete', C37 'low') and were not used as quantitative threshold evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

